INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('2a000000-0000-4000-8000-070000000005', '2a000000-0000-4000-8000-060000000005', 1, 'Some people think that cities should plant trees along every street, even if this means fewer parking spaces. To what extent do you agree or disagree? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', NULL, '{"type": "ESSAY", "task": "TASK_2", "minWords": 250, "passBand": 5.5}', 1, 'Many city streets are lined with parked cars rather than trees. Replacing some parking spaces with trees is a popular idea, and I largely agree with it, although the change should be made gradually.
