INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('2a000000-0000-4000-8000-070000000010', '2a000000-0000-4000-8000-060000000010', 1, 'Some people believe that protecting old forests is more important than building new homes. Others think that housing should come first. Discuss both these views and give your own opinion. Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', NULL, '{"type": "ESSAY", "task": "TASK_2", "minWords": 250, "passBand": 5.5}', 1, 'In many growing regions, land that is covered by old forest could also be used for new housing. Some people argue that the forest must be protected, while others believe that homes for people are more urgent. In my view, both needs can be met if building is planned carefully.
